mapper.select:
select seq, id, ref, step, depth, title, content, wdate, del, readcount
from qna
where seq = #{seq}

mapper.update:
update qna
set title = #{title},
    content = #{content}
where seq = #{seq}

mapper.delete:
delete from qna
where ref = (
    select ref
    from qna
    where seq = #{seq}
)

mapper.update:
update qna
set step = step + 1
where ref = (
    select ref
    from qna
    where seq = #{seq}
)
and step > (
    select step
    from qna
    where seq = #{seq}
)

mapper.select:
select auth
from member
where id = #{id}

mapper.update:
update qna
set readcount = readcount + 1
where seq = #{seq}
